private void startCell(boolean header) {
    if (tableDepth != 1 || !(stack.peek() instanceof TableRow)) {
        return;
    }
    TableCell cell = new TableCell();
    cell.setHeader(header || inHeaderRow);
    stack.peek().appendChild(cell);
    stack.push(cell);
}
